package com.smartspend.service;
import com.smartspend.dao.*;import com.smartspend.model.*;import java.time.*;import java.time.temporal.ChronoUnit;
public class NotificationService {private final BudgetDAO budgets=new BudgetDAO();private final RecurringExpenseDAO recurring=new RecurringExpenseDAO();private final NotificationDAO notifications=new NotificationDAO();public void refresh(int uid){for(Budget b:budgets.findForMonth(uid,LocalDate.now().getMonthValue(),LocalDate.now().getYear())){double p=b.getPercentage();if(p>=100)notifications.add(uid,"Budget exceeded",b.getCategoryName()+" budget is exceeded.","BUDGET");else if(p>=90)notifications.add(uid,"Budget critical",b.getCategoryName()+" budget is "+String.format("%.0f",p)+"% used.","BUDGET");}for(RecurringExpense r:recurring.findAll(uid)){long d=ChronoUnit.DAYS.between(LocalDate.now(),r.getNextPaymentDate());if(d>=0&&d<=3)notifications.add(uid,"Upcoming payment",r.getName()+" payment is due in "+d+" days.","RECURRING");}}}
